import{_ as a,o as t,c as n,a2 as s}from"./chunks/framework.BM5YPQmL.js";const h=JSON.parse('{"title":"ADR-004: Human-marked cues instead of speech recognition","description":"","frontmatter":{},"headers":[],"relativePath":"adr/004-human-marked-cues.md","filePath":"adr/004-human-marked-cues.md"}'),i={name:"adr/004-human-marked-cues.md"};function o(r,e,c,d,u,l){return t(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="adr-004-human-marked-cues-instead-of-speech-recognition" tabindex="-1">ADR-004: Human-marked cues instead of speech recognition <a class="header-anchor" href="#adr-004-human-marked-cues-instead-of-speech-recognition" aria-label="Permalink to &quot;ADR-004: Human-marked cues instead of speech recognition&quot;">​</a></h1><ul><li>Status: accepted, superseded in part by <a href="./013-assisted-cue-alignment.html">ADR-013</a> (machine-suggested cues) · Date: 2026-10-15</li></ul><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>The product must use no AI/ML (G3). (Since 1.0 this applies to the render engine; optional machine-suggested cues are covered by ADR-013.) Timing must survive re-recording a single sentence.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>The author marks the start of each script line with Space while listening (at 0.5×–1× speed). Word times are estimated from letter counts (SRS §5.2) or marked manually in word mode. An optional &quot;snap to onset&quot; uses a deterministic RMS-envelope rise detector.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>Marking a 90 s episode takes 2–3 minutes; re-recording a line means re-marking one line.</li><li>Animations reference lines and words (<code>l7:&#39;timeout&#39;</code>), so they follow the voice automatically.</li></ul>',8)])])}const p=a(i,[["render",o]]);export{h as __pageData,p as default};
